import ast,copy,hashlib,json,math
from pathlib import Path
r=json.load(open('runtime_context.json'));p=json.load(open('proposal.json'))
def validate(value,schema,path='"'$'"'):
 typ=schema.get('type')
 expected={'object':dict,'array':list,'string':str,'boolean':bool}
 if typ in expected: assert isinstance(value,expected[typ]),(path,typ,type(value))
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,v in enumerate(value): validate(v,schema.get('items',{}),path+'['+str(i)+']')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'missing')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=set(props),(path,'extra')
  for k,v in value.items():
   if k in props: validate(v,props[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4 and len({v['name'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
